sp_widget.css:
.heading-widget {
  text-align: center;
  padding: 40px;
  color: #ffffff;
  background: linear-gradient(135deg, #00f5a0, #00d9ff); /* Fluorescent teal to blue */
  border-radius: 25px;
  box-shadow: 0 0 30px rgba(0, 255, 255, 0.6);
  transform: translateY(0);
  transition: all 0.4s ease-in-out;
  border: 2px solid #00ffe0;
  animation: pulseGlow 3s infinite;
}

@keyframes pulseGlow {
  0% {
    box-shadow: 0 0 20px rgba(0, 255, 255, 0.4);
  }
  50% {
    box-shadow: 0 0 40px rgba(0, 255, 255, 0.8);
  }
  100% {
    box-shadow: 0 0 20px rgba(0, 255, 255, 0.4);
  }
}

.heading-widget:hover {
  transform: translateY(-10px);
  box-shadow: 0 0 50px rgba(0, 255, 255, 1);
}

.heading-widget h1 {
  margin-bottom: 20px;
  font-size: 3em;
  letter-spacing: 2px;
  text-shadow: 0 0 10px #00ffe0, 2px 2px 4px rgba(0, 0, 0, 0.6);
  font-weight: bold;
}

.heading-widget p {
  font-size: 1.5em;
  color: #e0ffe0;
  margin-bottom: 0;
  text-shadow: 0 0 5px #00ffe0;
}

